<?php
namespace App\Services\Wallet;use App\Models\{User,Wallet,WalletLedgerEntry,WalletReservation,WalletTopUp};use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class WalletService{public function for(User$o):Wallet{return Wallet::firstOrCreate(['studio_owner_id'=>$o->id]);}public function quote(int$minor):array{$c=config('wallet');if($minor<$c['minimum_top_up_minor']||$minor>$c['maximum_top_up_minor']||$minor%$c['top_up_multiple_minor']!==0)throw ValidationException::withMessages(['amount'=>'Enter an amount in multiples of ₹5 between ₹5 and ₹100,000.']);$tax=intdiv($minor*$c['gst_basis_points']+9999,10000);return['base_amount_minor'=>$minor,'tax_amount_minor'=>$tax,'total_amount_minor'=>$minor+$tax,'credit_units'=>intdiv($minor*$c['credit_scale'],$c['credit_value_minor']),'currency'=>$c['currency']];}public function pending(User$o,int$minor,string$key):WalletTopUp{$q=$this->quote($minor);return WalletTopUp::firstOrCreate(['idempotency_key'=>$key],$q+['uuid'=>(string)Str::uuid(),'wallet_id'=>$this->for($o)->id,'studio_owner_id'=>$o->id,'status'=>'pending']);}public function credit(WalletTopUp$t,string$payment):WalletTopUp{return DB::transaction(function()use($t,$payment){$t=WalletTopUp::lockForUpdate()->findOrFail($t->id);if($t->status==='paid')return$t;$w=Wallet::lockForUpdate()->findOrFail($t->wallet_id);$after=$w->available_credit_units+$t->credit_units;WalletLedgerEntry::create(['uuid'=>(string)Str::uuid(),'wallet_id'=>$w->id,'studio_owner_id'=>$t->studio_owner_id,'entry_type'=>'top_up_credit','direction'=>'credit','credit_units'=>$t->credit_units,'balance_after_units'=>$after,'currency'=>$t->currency,'money_amount_minor'=>$t->base_amount_minor,'reference_type'=>WalletTopUp::class,'reference_id'=>$t->uuid,'idempotency_key'=>'top-up:'.$t->uuid,'description'=>'Wallet top-up','occurred_at'=>now()]);$w->update(['available_credit_units'=>$after,'version'=>$w->version+1]);$t->update(['status'=>'paid','provider_payment_id'=>$payment,'paid_at'=>now()]);return$t;});}public function reserve(Wallet$wallet,int$units,string$purpose,string$refType,string$refId,string$key):WalletReservation{if(str_contains(strtolower($purpose),'whatsapp')||$purpose==='authentication_otp')throw ValidationException::withMessages(['wallet'=>'WhatsApp messaging is not a billable Wallet service.']);return DB::transaction(function()use($wallet,$units,$purpose,$refType,$refId,$key){if($r=WalletReservation::where('idempotency_key',$key)->first())return$r;$w=Wallet::lockForUpdate()->findOrFail($wallet->id);if($units<=0||$w->available_credit_units<$units)throw ValidationException::withMessages(['wallet'=>'You do not have enough credits for this action.']);$w->update(['available_credit_units'=>$w->available_credit_units-$units,'reserved_credit_units'=>$w->reserved_credit_units+$units,'version'=>$w->version+1]);return WalletReservation::create(['uuid'=>(string)Str::uuid(),'wallet_id'=>$w->id,'credit_units'=>$units,'purpose'=>$purpose,'reference_type'=>$refType,'reference_id'=>$refId,'idempotency_key'=>$key,'status'=>'reserved']);});}public function capture(WalletReservation$r):void{if(str_contains(strtolower($r->purpose),'whatsapp')||$r->purpose==='authentication_otp')throw ValidationException::withMessages(['wallet'=>'WhatsApp messaging is not a billable Wallet service.']);DB::transaction(function()use($r){$r=WalletReservation::lockForUpdate()->findOrFail($r->id);if($r->status==='captured')return;$w=Wallet::lockForUpdate()->findOrFail($r->wallet_id);$after=$w->available_credit_units;WalletLedgerEntry::firstOrCreate(['idempotency_key'=>'capture:'.$r->idempotency_key],['uuid'=>(string)Str::uuid(),'wallet_id'=>$w->id,'studio_owner_id'=>$w->studio_owner_id,'entry_type'=>'reservation_capture','direction'=>'debit','credit_units'=>$r->credit_units,'balance_after_units'=>$after,'currency'=>config('wallet.currency'),'reference_type'=>$r->reference_type,'reference_id'=>$r->reference_id,'description'=>'Paid service usage','safe_metadata'=>['purpose'=>$r->purpose],'occurred_at'=>now()]);$w->update(['reserved_credit_units'=>max(0,$w->reserved_credit_units-$r->credit_units),'version'=>$w->version+1]);$r->update(['status'=>'captured','captured_at'=>now()]);});}public function release(WalletReservation$r):void{DB::transaction(function()use($r){$r=WalletReservation::lockForUpdate()->findOrFail($r->id);if($r->status==='released')return;if($r->status!=='reserved')return;$w=Wallet::lockForUpdate()->findOrFail($r->wallet_id);$w->update(['available_credit_units'=>$w->available_credit_units+$r->credit_units,'reserved_credit_units'=>max(0,$w->reserved_credit_units-$r->credit_units),'version'=>$w->version+1]);$r->update(['status'=>'released','released_at'=>now()]);});}public function format(int$u):string{$s=(int)config('wallet.credit_scale');return$u%$s===0?(string)intdiv($u,$s):rtrim(rtrim(number_format($u/$s,1,'.',''),'0'),'.');}}
